        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(field_body_t)) || (!adcs_is_finite_vec3(field_rate_t_s)) ||
        (!isfinite(normalized_gain_nm_s_t)) || (!isfinite(max_dipole_a_m2)) ||
        (normalized_gain_nm_s_t < 0.0) || (max_dipole_a_m2 < 0.0)) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    b2 = adcs_vec3_dot(field_body_t, field_body_t);
    if (b2 <= ADCS_EPS_NORM * ADCS_EPS_NORM) {
        command->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        command->saturated_axes = 0U;
        return ADCS_E_DEGENERATE;
    }

    parallel_coeff = adcs_vec3_dot(field_rate_t_s, field_body_t) / b2;
    b_dot_perp = adcs_vec3_sub(field_rate_t_s, &adcs_vec3_scale(field_body_t, parallel_coeff));

    m_raw = adcs_vec3_scale(&b_dot_perp, -normalized_gain_nm_s_t / b2);

    m_norm = adcs_vec3_norm(&m_raw);
    command->saturated_axes = 0U;

    if (m_norm > max_dipole_a_m2) {
        scale_factor = max_dipole_a_m2 / m_norm;
        command->command = adcs_vec3_scale(&m_raw, scale_factor);
        command->saturated_axes = 7U;
    } else {
        command->command = m_raw;
    }

    return ADCS_OK;
}

